  //   4 = block-topology, 5 = multi-block-meta
  // names[] is indexed directly by ftype so names[0] is a placeholder.
  static const char *names[] = {
    NULL, // [0] — not a valid file type
    "field", // [1] — GKYL_FIELD_DATA_FILE
    "dynvector", // [2] — GKYL_DYNVEC_DATA_FILE
    "multi-range-field", // [3] — GKYL_MULTI_RANGE_DATA_FILE
    "block-topology", // [4] — GKYL_BLOCK_TOPO_DATA_FILE
    "multi-block-meta" // [5] — GKYL_MULTI_BLOCK_DATA_FILE
  };
  int nnames = (int)(sizeof(names) / sizeof(names[0]));

  if (ftype <= 0 || ftype >= nnames || names[ftype] == NULL) {
    lua_pushstring(L, "not-gkyl");
  } else {
    lua_pushstring(L, names[ftype]);
  }

  return 1;
}

/* -- G0.Zero.arrayNewFromFile(fname) -> grid_ud, array_ud  (or nil, nil on failure) -- */
static int
array_new_from_file_lw(lua_State *L)
{
  const char *fname = luaL_checkstring(L, 1);

  struct rect_grid_lw *g_lw = gkyl_malloc(sizeof(*g_lw));
  struct gkyl_array *arr = gkyl_grid_array_new_from_file(&g_lw->grid, fname);

  if (!arr) {
    gkyl_free(g_lw);
    lua_pushnil(L);
    lua_pushnil(L);
    return 2;
  }

}

void
gkyl_moment_multib_app_write(const gkyl_moment_multib_app *app, double tm, int frame)
{
  gkyl_moment_multib_app_write_field(app, tm, frame);
  for (int i = 0; i < app->num_species; ++i) {
    gkyl_moment_multib_app_write_species(app, i, tm, frame);
  }
}

void
gkyl_moment_multib_app_write_field(const gkyl_moment_multib_app *app, double tm, int frame)
{
  for (int i = 0; i < app->num_local_blocks; ++i) {
    gkyl_moment_app_write_field(app->singleb_apps[i], tm, frame);
  }

  if (app->has_field) {
    int rank;
    gkyl_comm_get_rank(app->comm, &rank);
    if (0 == rank) {
      cstr file_name = cstr_from_fmt("%s-%s_%d.gkyl", app->name, "field", frame);
      cstr topo_file_name = cstr_from_fmt("%s_btopo.gkyl", app->name);

      moment_multib_data_write(
        file_name.str,
        (struct moment_multib_output_meta){
          .frame = frame,
          .stime = tm,
          .topo_file_name = topo_file_name.str,
          .app_name = app->name,
        }
      );

      cstr_drop(&topo_file_name);
      cstr_drop(&file_name);
    }
  }

  gkyl_comm_barrier(app->comm);
}

void
gkyl_moment_multib_app_write_species(
  const gkyl_moment_multib_app *app, int sidx, double tm, int frame
)
{
  for (int i = 0; i < app->num_local_blocks; ++i) {
    gkyl_moment_app_write_species(app->singleb_apps[i], sidx, tm, frame);
  }

  int rank;
  gkyl_comm_get_rank(app->comm, &rank);
  if (0 == rank) {
    cstr file_name = cstr_from_fmt("%s-%s_%d.gkyl", app->name, app->species_name[sidx], frame);
    cstr topo_file_name = cstr_from_fmt("%s_btopo.gkyl", app->name);

    moment_multib_data_write(
      file_name.str,
      (struct moment_multib_output_meta){
        .frame = frame,
        .stime = tm,
        .topo_file_name = topo_file_name.str,
        .app_name = app->name,
      }
    );

    cstr_drop(&topo_file_name);
    cstr_drop(&file_name);
  }
